 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    points = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == 3]
    # Each seed creates an asymmetric four-color cross/target, pointing toward
    # the nearest grid edge according to the seed's position in the demo pattern.
    # The pattern is a 5x5 motif centered at seed, extending left/up 2 and right/down 2;
    # long arms continue to the corresponding borders.
    for r,c in points:
        # Color-coded concentric directional bars as in demonstrations.
        # motif rows: top edge of motif has 5 across; side edges 2; central seed retained.
        for dr in range(-2,3):
            rr=r+dr
            if 0 <= rr < h:
                for dc in range(-2,3):
                    cc=c+dc
                    if 0 <= cc < w:
                        if (dr == -2 and -2 <= dc <= 2) or (dc in (-2,2) and -1 <= dr <= 2):
                            out[rr][cc]=5 if (dr == -2 or dc == 0 and dr == -1) else 2
        # horizontal bands from seed toward boundaries, with border-adjacent stripe color
        for cc in range(w):
            if cc < c-2: out[r+2][cc]=2
            elif cc > c+2: out[r+2][cc]=2
        # Fill bottom row of motif as 8 across, seed row structure preserved
        for dc in range(-2,3):
            cc=c+dc
            if 0<=cc<w and 0<=r+2<h: out[r+2][cc]=8
        for cc in range(w):
            if cc < c-2 or cc > c+2:
                if 0<=r+2<h: out[r+2][cc]=2
    return out

